import React, { useState, useEffect } from "react";
import { useSearchParams } from "react-router-dom";
import {
  Box,
  Typography,
  Button,
  Card,
  CardContent,
  CircularProgress,
  Alert,
  Divider,
} from "@mui/material";
import FaceIcon from "@mui/icons-material/Face";
import CheckCircleIcon from "@mui/icons-material/CheckCircle";
import ShieldIcon from "@mui/icons-material/Shield";
import LightbulbOutlinedIcon from "@mui/icons-material/LightbulbOutlined";
import VisibilityOutlinedIcon from "@mui/icons-material/VisibilityOutlined";
import SmartphoneOutlinedIcon from "@mui/icons-material/SmartphoneOutlined";
import {
  buildFacePidOptions,
  launchFaceRdCapture,
  isAndroidDevice,
  FACE_RD_PLAYSTORE_URL,
} from "../../common/faceAuth/faceRdService";
import { dailyAuth } from "../../api/login/Login";

const FaceAuthBridgePage = () => {
  const [searchParams] = useSearchParams();
  const token = searchParams.get("token");
  const userId = searchParams.get("userId");
  const retailerName = searchParams.get("name") || "Retailer";
  const bank = searchParams.get("bank") || "aeps1";

  const [loading, setLoading] = useState(false);
  const [authSuccess, setAuthSuccess] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");
  const [location, setLocation] = useState({ latitude: "", longitude: "" });
  const isAndroid = isAndroidDevice();

  useEffect(() => {
    if (token) {
      localStorage.setItem("userIdToken", token);
      localStorage.setItem("userToken", token);
    }

    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          setLocation({
            latitude: pos.coords.latitude,
            longitude: pos.coords.longitude,
          });
        },
        (err) => {
          console.warn("Geolocation warning in bridge:", err.message);
        }
      );
    }
  }, [token]);

  const handleStartFaceScan = () => {
    setErrorMessage("");
    const pidXml = buildFacePidOptions(false);

    if (isAndroid) {
      launchFaceRdCapture(pidXml);
    } else {
      setErrorMessage(
        "Aadhaar FaceRD is supported on Android phones. Please open this page in Google Chrome on your Android mobile."
      );
    }
  };

  const handleSubmitPidData = async (xmlString) => {
    if (!xmlString) {
      setErrorMessage("No biometric data provided.");
      return;
    }
    setLoading(true);
    setErrorMessage("");

    try {
      let base64Data = "";
      try {
        base64Data = window.btoa(unescape(encodeURIComponent(xmlString)));
      } catch (e) {
        base64Data = window.btoa(xmlString);
      }

      const payload = {
        accessmodetype: "site",
        latitude: location.latitude || "28.6139",
        longitude: location.longitude || "77.2090",
        data: base64Data,
        user_id: userId || localStorage.getItem("userIdToken"),
        bank: bank || "aeps1",
        authType: "face",
      };

      const res = await dailyAuth(payload);
      if (
        res?.data?.statusCode === 200 ||
        res?.data?.status_Code === 200 ||
        res?.data?.error === false
      ) {
        setAuthSuccess(true);
      } else {
        setErrorMessage(res?.data?.message || "Daily Auth Failed. Please try again.");
      }
    } catch (err) {
      setErrorMessage(
        err?.response?.data?.message || err?.message || "An error occurred during Face Auth submission."
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box
      sx={{
        minHeight: "100vh",
        bgcolor: "#f1f5f9",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        p: 2,
      }}
    >
      <Card
        sx={{
          maxWidth: 440,
          width: "100%",
          borderRadius: "24px",
          boxShadow: "0 12px 36px rgba(15, 23, 42, 0.12)",
          overflow: "hidden",
          border: "1px solid #e2e8f0",
        }}
      >
        {/* Top Header */}
        <Box
          sx={{
            background: "linear-gradient(135deg, #193968 0%, #0d1b2a 100%)",
            color: "#ffffff",
            p: 3,
            textAlign: "center",
          }}
        >
          <Box
            sx={{
              width: 56,
              height: 56,
              borderRadius: "50%",
              bgcolor: "rgba(255, 255, 255, 0.12)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              mx: "auto",
              mb: 1.5,
            }}
          >
            <FaceIcon sx={{ fontSize: 32, color: "#60a5fa" }} />
          </Box>
          <Typography sx={{ fontWeight: 800, fontSize: "19px", letterSpacing: 0.3 }}>
            Aadhaar Face Auth
          </Typography>
          <Typography sx={{ fontSize: "12px", color: "#94a3b8", mt: 0.3 }}>
            AePS Daily 2FA Verification
          </Typography>
        </Box>

        <CardContent sx={{ p: 3 }}>
          {authSuccess ? (
            <Box sx={{ textAlign: "center", py: 2 }}>
              <CheckCircleIcon sx={{ fontSize: 64, color: "#10b981", mb: 1.5 }} />
              <Typography sx={{ fontWeight: 800, fontSize: "20px", color: "#065f46", mb: 0.5 }}>
                Auth Successful!
              </Typography>
              <Typography sx={{ fontSize: "13.5px", color: "#475569", lineHeight: 1.5, mb: 2.5 }}>
                Aadhaar Daily Auth complete ho chuka hai. Aapka PC screen unlock ho gaya hai.
              </Typography>
              <Alert severity="success" sx={{ borderRadius: "12px", fontSize: "13px" }}>
                Aap is tab ko band kar sakte hain.
              </Alert>
            </Box>
          ) : (
            <Box>
              {/* Retailer Info */}
              <Box
                sx={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  p: 1.5,
                  borderRadius: "14px",
                  bgcolor: "#f8fafc",
                  border: "1px solid #e2e8f0",
                  mb: 2.5,
                }}
              >
                <Box>
                  <Typography sx={{ fontSize: "11px", color: "#64748b", fontWeight: 600 }}>
                    RETAILER NAME
                  </Typography>
                  <Typography sx={{ fontSize: "14.5px", fontWeight: 800, color: "#1e293b" }}>
                    {retailerName}
                  </Typography>
                </Box>
                <Box
                  sx={{
                    display: "flex",
                    alignItems: "center",
                    gap: 0.5,
                    px: 1,
                    py: 0.4,
                    borderRadius: "8px",
                    bgcolor: "#ecfdf5",
                    color: "#059669",
                  }}
                >
                  <ShieldIcon sx={{ fontSize: 14 }} />
                  <Typography sx={{ fontSize: "11px", fontWeight: 700 }}>Ready</Typography>
                </Box>
              </Box>

              {/* 3 Step Retailer Friendly Instructions */}
              <Typography sx={{ fontSize: "13px", fontWeight: 800, color: "#334155", mb: 1.2 }}>
                📌 Chehra Scan Karne Ke Niyam (Easy Steps):
              </Typography>

              <Box sx={{ display: "flex", flexDirection: "column", gap: 1.2, mb: 3 }}>
                <Box
                  sx={{
                    display: "flex",
                    alignItems: "center",
                    gap: 1.2,
                    p: 1.2,
                    borderRadius: "12px",
                    bgcolor: "#eff6ff",
                    border: "1px solid #bfdbfe",
                  }}
                >
                  <LightbulbOutlinedIcon sx={{ color: "#2563eb", fontSize: 20, flexShrink: 0 }} />
                  <Typography sx={{ fontSize: "12px", color: "#1e40af", lineHeight: 1.4 }}>
                    <strong>1. Achhi Roshni:</strong> Chehre par achhi light ho aur chashma/topi hata lein.
                  </Typography>
                </Box>

                <Box
                  sx={{
                    display: "flex",
                    alignItems: "center",
                    gap: 1.2,
                    p: 1.2,
                    borderRadius: "12px",
                    bgcolor: "#f0fdf4",
                    border: "1px solid #bbf7d0",
                  }}
                >
                  <SmartphoneOutlinedIcon sx={{ color: "#16a34a", fontSize: 20, flexShrink: 0 }} />
                  <Typography sx={{ fontSize: "12px", color: "#166534", lineHeight: 1.4 }}>
                    <strong>2. Phone Seedha:</strong> Phone ko aakhon ke samne seedha pakdein.
                  </Typography>
                </Box>

                <Box
                  sx={{
                    display: "flex",
                    alignItems: "center",
                    gap: 1.2,
                    p: 1.2,
                    borderRadius: "12px",
                    bgcolor: "#fdf4ff",
                    border: "1px solid #f5d0fe",
                  }}
                >
                  <VisibilityOutlinedIcon sx={{ color: "#9333ea", fontSize: 20, flexShrink: 0 }} />
                  <Typography sx={{ fontSize: "12px", color: "#86198f", lineHeight: 1.4 }}>
                    <strong>3. Aankhein Jhapkayen:</strong> Camera me dekhein aur <strong>aankhein 1 baar blink karein</strong>.
                  </Typography>
                </Box>
              </Box>

              {errorMessage && (
                <Alert severity="error" sx={{ mb: 2, borderRadius: "12px", fontSize: "12.5px" }}>
                  {errorMessage}
                </Alert>
              )}

              {/* Scan Trigger Button */}
              <Button
                fullWidth
                variant="contained"
                onClick={handleStartFaceScan}
                disabled={loading}
                sx={{
                  py: 1.6,
                  borderRadius: "14px",
                  background: "linear-gradient(135deg, #193968 0%, #2563eb 100%)",
                  fontWeight: 800,
                  fontSize: "15px",
                  textTransform: "none",
                  boxShadow: "0 8px 20px rgba(37, 99, 235, 0.3)",
                  "&:hover": {
                    background: "linear-gradient(135deg, #142c52 0%, #1d4ed8 100%)",
                  },
                }}
              >
                {loading ? (
                  <CircularProgress size={24} sx={{ color: "#fff" }} />
                ) : (
                  "📸 Chehra Scan Karein (Start Face Scan)"
                )}
              </Button>

              {/* PlayStore Help */}
              <Box sx={{ textAlign: "center", mt: 2 }}>
                <Typography sx={{ fontSize: "11px", color: "#94a3b8" }}>
                  Agar Face RD app nahi hai, toh{" "}
                  <a
                    href={FACE_RD_PLAYSTORE_URL}
                    target="_blank"
                    rel="noreferrer"
                    style={{ color: "#2563eb", fontWeight: 700, textDecoration: "none" }}
                  >
                    Play Store se Download karein ↗
                  </a>
                </Typography>
              </Box>
            </Box>
          )}
        </CardContent>
      </Card>
    </Box>
  );
};

export default FaceAuthBridgePage;
